<div class="page-heading dashboard-heading"><div><span class="eyebrow">MERCHANT WORKSPACE</span><h1>Dashboard tokomu</h1><p><?= e($merchant['business_name']) ?> · Status <span class="status status-<?= e($merchant['verification_status']) ?>"><?= e($merchant['verification_status']) ?></span></p></div><?php if($merchant['verification_status']==='disetujui'): ?><a href="?page=product-form" class="btn btn-primary">＋ Tambah produk surplus</a><?php endif; ?></div>
<?php if($merchant['verification_status']!=='disetujui'): ?><div class="panel pending-panel"><div class="pending-icon">◷</div><h2><?= $merchant['verification_status']==='menunggu'?'Pengajuan sedang ditinjau':'Pengajuan merchant ditolak' ?></h2><p><?= $merchant['verification_status']==='menunggu'?'Admin akan memeriksa dokumen usaha sebelum kamu bisa menerbitkan listing.':'Alasan: '.e($merchant['rejection_reason']??'Tidak tersedia').'. Silakan hubungi admin untuk informasi lebih lanjut.' ?></p></div><?php else: ?><div class="metrics-grid"><div class="metric-card"><span>Jumlah listing</span><strong><?= count($products) ?></strong><small>Produk yang pernah dibuat</small></div><div class="metric-card"><span>Pesanan terbaru</span><strong><?= count($orders) ?></strong><small>Termasuk riwayat transaksi</small></div><div class="metric-card"><span>Merchant verified</span><strong>✓</strong><small>Akun aktif untuk berjualan</small></div></div><section class="section"><div class="section-heading"><div><h2>Listing produkmu</h2><p class="muted">Diskon diizinkan antara 30–70%.</p></div></div><?php if(!$products): ?><div class="empty-state compact"><h3>Belum ada listing</h3><p>Mulai selamatkan makanan surplus dengan menerbitkan produk pertamamu.</p><a href="?page=product-form" class="btn btn-primary">Tambah produk</a></div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Produk</th><th>Harga normal</th><th>Diskon</th><th>Stok</th><th>Batas konsumsi</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($products as $p): ?><tr><td><strong><?= e($p['name']) ?></strong><small><?= e($p['category']) ?></small></td><td><?= money($p['normal_price']) ?></td><td><span class="discount-text">-<?= (int)$p['discount_percent'] ?>%</span></td><td><?= (int)$p['stock'] ?></td><td><?= e(date('d M Y',strtotime($p['expiry_date']))) ?></td><td><span class="status <?= $p['is_active']?'status-disetujui':'status-ditolak' ?>"><?= $p['is_active']?'Aktif':'Nonaktif' ?></span></td><td class="actions"><a href="?page=product-form&id=<?= (int)$p['product_id'] ?>">Ubah</a><form method="post" class="inline" data-confirm="Nonaktifkan listing ini?"><?= csrf_field() ?><input type="hidden" name="action" value="deactivate_product"><input type="hidden" name="product_id" value="<?= (int)$p['product_id'] ?>"><button class="link-danger">Nonaktifkan</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section><?php endif; ?>
<section class="section"><div class="section-heading"><div><h2>Pesanan terbaru</h2><p class="muted">Lihat dan tindak lanjuti pesanan yang sudah dibayar.</p></div><a href="?page=merchant-orders">Lihat semua →</a></div><?php if(empty($orders)): ?><div class="panel empty-line">Belum ada pesanan masuk.</div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Order</th><th>Konsumen</th><th>Produk</th><th>Total</th><th>Status</th></tr></thead><tbody><?php foreach($orders as $o): ?><tr><td>#ORD-<?= (int)$o['order_id'] ?></td><td><?= e($o['consumer_name']) ?></td><td><?= e($o['product_names']) ?></td><td><?= money($o['total_amount']) ?></td><td><span class="status status-<?= e($o['status']) ?>"><?= e(str_replace('_',' ',$o['status'])) ?></span></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
